import openpyxl
wb=openpyxl.load_workbook('init.xlsx')
ws=wb['Sheet1']
f_vals=[ws.cell(row=r,column=6).value for r in range(2,7)]
f_set=set(v for v in f_vals if v)
data={}
for r in range(2,8):
    for c in range(1,4):
        data[(r,c)]=ws.cell(row=r,column=c).value
rows=[r for r in range(2,8) if ws.cell(row=r,column=1).value in f_set]
for r in range(2,8):
    for c in range(1,4):
        ws.cell(row=r,column=c).value=None
for i,r in enumerate(rows):
    for c in range(1,4):
        ws.cell(row=2+i,column=c).value=data[(r,c)]
# retain autofilter
ws.auto_filter.ref='A1:C7'
wb.save('output.xlsx')
print('saved', rows)
